function transform (message, context) {

  var headers = Object.keys(message.payload);

  var vals = Object.values(message.payload);

vals = vals.map(String);  // convert every value to String
if (context.quoteStrings) {
    headers = headers.map(v => v.replaceAll('"', '""')) 
                .map(v => `"${v}"`);  
    vals = vals.map(v => v.replaceAll('"', '""')) 
                .map(v => `"${v}"`);  
}
// Delimiter selection
switch (context.delimiter) {
  case "tab": 
    vals = vals.join("\t"); 
     context.headers = headers.join("\t");
    break;
  case "comma":
     vals = vals.join(",");
      context.headers = headers.join(",");
     break;
  case "semicolon":
      vals = vals.join(";");
      context.headers = headers.join(";");
      break;
  case "pipe":
      vals = vals.join("|");
      context.headers = headers.join("|");
      break;
}// delimiter-separated
message.payload = vals;
return message

}

